package com.mushafi.app;
import android.content.Context;import org.json.*;import java.io.*;import java.net.*;
/** Publisher-timed verses backed by the same full chapter; never borrow another reader's timestamps. */
final class TimedVerseSource {
 interface Cancel{boolean get();} interface Connection{void set(HttpURLConnection c);}
 private static String folder(int reader)throws IOException{switch(reader){case 133:return "maher-muaiqly/r3";case 1001:return "ali-hudhaifi/r1";case 1002:return "muhammad-ayyub/r1";case 1003:return "khalid-mohanna/r1";case 1004:return "ibrahim-akhdar/r1";default:throw new IOException("unverified timed reader");}}
 static JSONObject spec(JSONObject catalog,int reader)throws Exception{folder(reader);JSONObject s=catalog.getJSONObject(String.valueOf(reader));if(!s.optBoolean("verseTimingVerified",false)||!"mp3quran-primary-v1".equals(s.optString("sourceVersion")))throw new IOException("timed reader");return s;}
 static int chapter(String key)throws Exception{if(key==null||!key.matches("[1-9][0-9]{0,2}:[1-9][0-9]{0,2}"))throw new IOException("verse key");int c=Integer.parseInt(key.split(":")[0]);if(c>114)throw new IOException("chapter");return c;}
 static int[] bounds(JSONObject catalog,int reader,String key)throws Exception{JSONObject s=spec(catalog,reader);JSONArray row=s.getJSONObject("segments").getJSONArray(key);if(row.length()!=3||row.getInt(0)!=chapter(key)||row.getInt(1)<0||row.getInt(2)<=row.getInt(1))throw new IOException("bounds");return new int[]{row.getInt(1),row.getInt(2)};}
 static String url(JSONObject catalog,int reader,String key)throws Exception{JSONObject s=spec(catalog,reader);int c=chapter(key);String value=s.getJSONObject("chapterUrls").getString(String.valueOf(c)),expected=String.format(java.util.Locale.US,"https://cdn.mp3quran.net/audio/"+folder(reader)+"/%03d.mp3",c);if(!expected.equals(value))throw new IOException("source URL");return value;}
 static File file(Context context,int reader,String key)throws Exception{folder(reader);return new File(context.getFilesDir(),"surah-audio/mp3quran-primary-v1/"+reader+"/"+chapter(key)+".mp3");}
 static long size(JSONObject catalog,int reader,String key)throws Exception{long n=spec(catalog,reader).getJSONObject("chapterSizes").getLong(String.valueOf(chapter(key)));if(n<129||n>350000000L)throw new IOException("size");return n;}
 static void download(JSONObject catalog,int reader,String key,File target,Cancel cancelled,Connection state)throws Exception{long expected=size(catalog,reader,key);if(target.length()==expected)return;target.getParentFile().mkdirs();File temp=new File(target.getAbsolutePath()+".part");HttpURLConnection connection=(HttpURLConnection)new URL(url(catalog,reader,key)).openConnection();state.set(connection);connection.setConnectTimeout(20000);connection.setReadTimeout(30000);connection.setInstanceFollowRedirects(false);try{if(connection.getResponseCode()!=200)throw new IOException("HTTP");String type=connection.getContentType();if(type==null||!(type.startsWith("audio/")||type.startsWith("application/octet-stream")))throw new IOException("audio");long got=0;try(InputStream in=connection.getInputStream();FileOutputStream out=new FileOutputStream(temp)){byte[] b=new byte[32768];int n;while((n=in.read(b))!=-1){if(cancelled.get())throw new InterruptedIOException();got+=n;if(got>expected)throw new IOException("length");out.write(b,0,n);}}if(got!=expected||cancelled.get())throw new IOException("incomplete");if(!temp.renameTo(target))throw new IOException("cache");}finally{connection.disconnect();state.set(null);temp.delete();}}
}
